recorded={r['path'] for r in ledger['records']}
for path,n in notes.items():
    if path in recorded:continue
    source=load_symbols(path);lines=len((ROOT/path).read_text(encoding='utf-8-sig').splitlines())
    review={'responsibilities':n['role'],'symbols':[],'callables':'NOT_APPLICABLE: no source callable declarations in this document/configuration',
            'non_callable_analysis':n,'reviewed_line_spans':[[1,lines]],'status':'REVIEWED_STATIC_COMPLETE_FILE',
            'scope_limit':'Full manual file read and specific claim reconciliation; no runtime acceptance inferred'}
    shard=save_review('parent',path,review)
    report=WORK/'Deep-Audit/File-Reports'/Path(path+'.md');report.parent.mkdir(parents=True,exist_ok=True)
    if report.exists():raise ValueError('Refuse overwriting preexisting parent report '+path)
    sections=[f'# {path}',f'Baseline `{BASELINE}`. Worktree SHA256 `{source["worktree_sha256"]}`; Git blob SHA256 `{source["git_blob_sha256"]}`. Read lines1–{lines}.',
              'Status: full static document/configuration review; functions NOT_APPLICABLE.']
    for key,value in n.items():sections.extend(['## '+key, '\n'.join('- '+s for s in value) if isinstance(value,list) else value])
    sections.extend(['## Scope and effects','Inputs are human/operator/build configuration; outputs are instructions/build membership/ignore behavior as described above. No application business logic, XAML, packages, databases, services or printers modified. Runtime/hardware claims remain explicitly unverified.'])
    report.write_text('\n\n'.join(sections)+'\n',encoding='utf8')
    ledger['records'].append({'path':path,'sha256':source['worktree_sha256'],'git_blob_sha256':source['git_blob_sha256'],'status':'REVIEWED_STATIC_COMPLETE_FILE','reviewed_line_spans':[[1,lines]],'report':str(report.relative_to(WORK)).replace('\\','/'),'symbols':'NOT_APPLICABLE','knowledge':str(shard.relative_to(WORK)).replace('\\','/')})
    ledger['reviewed_count']=len(ledger['records']);ledger['remaining_count']=18-len(ledger['records']);atomic_json(ledger_path,ledger)
    atomic_json(WORK/'Sub-Agents/Checkpoints/parent-file-review.json',{'at_utc':now(),'last_completed_file':path,'last_completed_function':'NOT_APPLICABLE','completed_files':ledger['reviewed_count'],'remaining_files':ledger['remaining_count'],'next_action':'Parent18 document/config file reads complete. Continue independent route receipt quality challenges, non-C# symbol map and remaining audit categories; no commit/push until all final gates.'})
